import { existsSync, readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { TOTAL_AYAHS, ayahIdOf, endOf, juzOf, locate, pageOf, pageRange, type Meta } from './data'

const file = new URL('../public/data/meta.json', import.meta.url)
// The data is generated by tools/build_data.py; without it these checks have nothing to run on.
describe.skipIf(!existsSync(file))('Quran data', () => {
  const meta: Meta = JSON.parse(readFileSync(file, 'utf8'))

  it('has 114 surahs, 604 pages, 30 juz and 6236 ayahs', () => {
    expect(meta.surahs).toHaveLength(114)
    expect(meta.pages).toHaveLength(604)
    expect(meta.juz).toHaveLength(30)
    expect(meta.surahs.reduce((n, s) => n + s.ayahs, 0)).toBe(TOTAL_AYAHS)
  })

  it('puts Maryam 19:1-11 on page 305 in juz 16 (as in the Madani mushaf)', () => {
    const first = ayahIdOf(meta, 19, 1)
    expect(pageOf(meta, first)).toBe(305)
    expect(juzOf(meta, first)).toBe(16)
    expect(pageRange(meta, 305)).toEqual({ first, last: ayahIdOf(meta, 19, 11) })
    expect(pageOf(meta, ayahIdOf(meta, 19, 12))).toBe(306)
  })

  it('knows well-known pages', () => {
    expect(pageOf(meta, 1)).toBe(1)
    expect(pageOf(meta, ayahIdOf(meta, 2, 1))).toBe(2)
    expect(pageOf(meta, ayahIdOf(meta, 17, 24))).toBe(284)
    expect(pageOf(meta, TOTAL_AYAHS)).toBe(604)
  })

  it('page ranges cover every ayah exactly once, in order', () => {
    let next = 1
    for (let p = 1; p <= 604; p++) {
      const { first, last } = pageRange(meta, p)
      expect(first).toBe(next)
      expect(last).toBeGreaterThanOrEqual(first)
      next = last + 1
    }
    expect(next).toBe(TOTAL_AYAHS + 1)
    expect(() => pageRange(meta, 605)).toThrow()
  })

  it('locate and ayahIdOf are inverses', () => {
    for (const id of [1, 7, 8, 2024, 2251, 6236]) {
      const { surah, ayah } = locate(meta, id)
      expect(ayahIdOf(meta, surah, ayah)).toBe(id)
    }
  })

  it('plays to the end of the page, surah, juz and Quran', () => {
    const id = ayahIdOf(meta, 19, 3)
    expect(endOf(meta, id, 'page')).toBe(ayahIdOf(meta, 19, 11))
    expect(endOf(meta, id, 'surah')).toBe(ayahIdOf(meta, 19, 98))
    expect(endOf(meta, id, 'quran')).toBe(TOTAL_AYAHS)
    expect(endOf(meta, id, 'ayah')).toBe(id)
    expect(juzOf(meta, endOf(meta, id, 'juz'))).toBe(16)
    expect(juzOf(meta, endOf(meta, id, 'juz') + 1)).toBe(17)
  })
})
